const expected_revision=input.expected_revision==null||input.expected_revision===""?0:Number(input.expected_revision);
if(!Number.isSafeInteger(expected_revision)||expected_revision<0) throw new Error("expected_revision_invalid");
const response=await callTool("recipe--application_data_v1",{operation:"save",namespace:"cib-accompagnement",record_key:data.id,data,expected_revision});
const payload=response&&response.data?response.data:response;
if(!payload||!payload.record||typeof payload.record!=="object") throw new Error("broker_record_invalid");
const item=payload.record;
if(item.namespace!=="cib-accompagnement"||item.key!==data.id) throw new Error("broker_record_identity_invalid");
if(!Number.isSafeInteger(item.revision)||item.revision<0) throw new Error("broker_revision_invalid");
if(!item.data||typeof item.data!=="object") throw new Error("broker_record_data_invalid");
const permissions=item.permissions;
if(!permissions||typeof permissions.can_read!=="boolean"||typeof permissions.can_write!=="boolean"||typeof permissions.can_manage!=="boolean") throw new Error("broker_permissions_invalid");
const shares=Array.isArray(item.shares)?item.shares:[];const permissions_summary="Read: "+(permissions.can_read===true?"yes":"no")+" · Write: "+(permissions.can_write===true?"yes":"no")+" · Share: "+(permissions.can_manage===true?"yes":"no");const share_count=shares.length;
const displayValue=(value, labels)=>labels[value]??value??"";
const source=item.data||{};const display={status:displayValue(source.etat,{pret_a_revoir:"Ready for review",a_qualifier:"Needs review",brouillon:"Draft",bloque:"Blocked",en_cours:"In progress"}),worker:displayValue(source.decision?.routing?.worker,{veille:"Watch",contenu:"Content",accompagnement:"Support",human_review:"Human review"}),verdict:displayValue(source.decision?.research?.verdict,{sufficient:"Sufficient",insufficient:"Insufficient",collect_more:"Collect more evidence",human_review:"Human review"}),review:displayValue(source.decision?.decision,{accepted:"Accepted",rework:"Rework",human_review:"Human review"})};
return {display,record:item.data,content:JSON.stringify(item.data,null,2),revision:item.revision,owner_user_id:typeof item.owner_user_id==="string"?item.owner_user_id:"",permissions,permissions_summary,shares,share_count,path:"/company-in-a-box/accompagnement/"+item.key};
